import sys
input = sys.stdin.read

def solve(n, k):
    if k > n * n:
        return -1

    matrix = [[0] * n for _ in range(n)]

    for i in range(n):
        if k == 0:
            break
        if k >= 1:
            matrix[i][i] = 1
            k -= 1
        for j in range(i + 1, n):
            if k >= 2:
                matrix[i][j] = 1
                matrix[j][i] = 1
                k -= 2
            else:
                break

    return matrix if k == 0 else -1

def main():
    data = input().strip()
    n, k = map(int, data.split())

    result = solve(n, k)
    if result == -1:
        print(-1)
    else:
        for row in result:
            print(' '.join(map(str, row)))

if __name__ == '__main__':
    main()

